import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

import '../../closet/application/closet_controller.dart';
import '../../closet/infrastructure/accessory_model_api.dart';
import '../application/ports.dart';
import '../domain/glasses.dart';

/// Test models in `assets/try_on/`, generated by `tool/make_sample_glasses.py` with the
/// same contract as virtual-try-on-service (metres, 14 cm, origin on the nose bridge).
const sampleGlasses = [
  GlassesOption.sample(
    id: 'sample:classic_black',
    name: 'Classic Black',
    asset: 'assets/try_on/classic_black.glb',
  ),
  GlassesOption.sample(
    id: 'sample:round_gold_sun',
    name: 'Round Gold Sun',
    asset: 'assets/try_on/round_gold_sun.glb',
  ),
  GlassesOption.sample(
    id: 'sample:tortoise_rect',
    name: 'Tortoise',
    asset: 'assets/try_on/tortoise_rect.glb',
  ),
];

/// Test models are shown in debug builds, or with --dart-define=TRY_ON_SAMPLES=true.
const showSampleGlasses = kDebugMode || bool.fromEnvironment('TRY_ON_SAMPLES');

/// Glasses of the user's closet whose 3D model is AR-ready, plus the test models.
class ClosetGlassesCatalog implements GlassesCatalog {
  ClosetGlassesCatalog({
    required this.closet,
    required this.models,
    this.includeSamples = showSampleGlasses,
    AssetBundle? bundle,
  }) : _bundle = bundle ?? rootBundle;

  final ClosetController closet;
  final AccessoryModelApi models;
  final bool includeSamples;
  final AssetBundle _bundle;

  // Models are a few hundred KB: keeping the ones already used makes switching instant.
  static const _cacheSize = 6;
  final _cache = <String, Uint8List>{};

  @override
  Future<List<GlassesOption>> options() async {
    final samples = includeSamples ? sampleGlasses : const <GlassesOption>[];
    if (!closet.loaded) await closet.load();
    final glasses = {
      for (final g in closet.garments)
        if (g.model3dCategory == 'glasses') g.id: g,
    };
    if (glasses.isEmpty) return samples;
    try {
      final summaries = await models.listModels(glasses.keys.toList());
      final own = [
        for (final s in summaries)
          if (s.arReady && glasses[s.garmentId] != null)
            GlassesOption.garment(
              garmentId: s.garmentId,
              name: glasses[s.garmentId]!.name,
              fit: GlassesFit.fromJson(s.arFit),
            ),
      ];
      return [...own, ...samples];
    } catch (_) {
      // Without the 3D service the test models still let the user try the feature.
      if (samples.isNotEmpty) return samples;
      rethrow;
    }
  }

  @override
  Future<GlassesFit> saveFit(GlassesOption option, GlassesFit fit) async {
    final id = option.garmentId;
    if (id == null) throw const FaceTryOnException('SAMPLE_NOT_CALIBRATABLE');
    final saved = await models.saveArFit(
      id,
      offsetM: [fit.offsetX, fit.offsetY, fit.offsetZ],
      scale: fit.scale,
      pitchDeg: fit.pitchDeg,
    );
    return GlassesFit.fromJson(saved);
  }

  @override
  Future<Uint8List> model(GlassesOption option) async {
    final cached = _cache.remove(option.id);
    if (cached != null) return _cache[option.id] = cached;
    final Uint8List bytes;
    if (option.sampleAsset case final asset?) {
      final data = await _bundle.load(asset);
      bytes = data.buffer.asUint8List(data.offsetInBytes, data.lengthInBytes);
    } else {
      bytes = await models.download(option.garmentId!);
    }
    if (_cache.length >= _cacheSize) _cache.remove(_cache.keys.first);
    return _cache[option.id] = bytes;
  }
}
